const DOCUMENTS = [{"id": "means", "title": "Ideology wars", "author": "Marianne Means", "date": "24 April 1996", "year": 1996, "kind": "Press", "outlet": "South Florida Sun Sentinel · p. 19", "url": "https://www.newspapers.com/image/238744873/", "quote": "When bad people make bad things happen, our national psyche drives us to search for a deep meaning.", "selects": "Political affiliations, the Oklahoma City comparison, and demands for an ideological explanation.", "argument": "Means challenges attempts to assign responsibility to liberalism or environmentalism. Yet her account also explains violence through an individualized picture of frustration and madness.", "context": "A syndicated column reproduced in the newspaper. Its display quotation and accompanying cartoon organize the reading before the argument begins.", "image": "assets/ideology-wars.jpg", "carrier": "Newspaper scan", "locator": "Attached bundle N01 · PDF page 1", "verification": "Scan inspected", "relation": "Compare with Mickelson’s report: a columnist’s intervention and a reporter’s use of expert testimony.", "pair": "taylor", "sourceTitle": "Ideology wars"}, {"id": "taylor", "title": "Thin link between radicals, bomber", "author": "Sandy Mickelson", "date": "11 April 1996", "year": 1996, "kind": "Press", "outlet": "Oshkosh Northwestern · p. 11", "url": "https://www.newspapers.com/image/247845486/", "quote": "Thin link between radicals, bomber", "selects": "An expert’s distinction between expressed affinity and the positions of environmental groups.", "argument": "The report brings Bron Taylor’s knowledge of radical environmentalism to bear on the association being made around Kaczynski. Similarity is itself an object of dispute.", "context": "The headline and subheading foreground a challenge to comparison. Read the clipping as a journalistic construction of expertise, as well as a source about the dispute.", "image": "assets/thin-link.jpg", "carrier": "Newspaper scan", "locator": "Attached bundle N01 · PDF page 16", "verification": "Scan inspected", "relation": "Paired analytically with Means; no direct reply between these articles is asserted.", "pair": "means", "sourceTitle": "Thin link between radicals, bomber"}, {"id": "crash", "title": "Crash the Parties!", "author": "UNAPACK NYC", "date": "1996", "year": 1996, "kind": "Campaign", "outlet": "NOT BORED! · no. 26", "url": "https://notbored.org/crash.html", "quote": "casting an absurd protest vote", "selects": "The widely published author, the electoral non-choice, and the absurdity of a candidate who would not serve.", "argument": "The NYC statement turns the Unabomber into an electoral intervention. The intended object is a protest vote; its significance is made through juxtaposition with the available candidates.", "context": "This is the campaign’s own announcement. Its rhetoric should be read alongside reporting on the campaign and disagreements between its participants.", "image": "assets/crash.gif", "carrier": "Campaign graphic + HTML", "locator": "Third substantive paragraph of the press release", "verification": "Publisher text checked", "imageCaption": "Graphic reproduced with the press release on NOT BORED!; not a facsimile of the complete release.", "relation": "Compare with Brown’s account of the relationship between NYC and Boston.", "pair": "brown", "sourceTitle": "Crash the Parties!"}, {"id": "brown", "title": "One campaign, different projects", "author": "Bill Brown, interviewed by Joey Manley", "date": "1996", "year": 1996, "kind": "Interview", "outlet": "NOT BORED!", "url": "https://notbored.org/manley.html", "quote": "There is no real ideological unity between New York and Boston.", "selects": "Decentralized organizing, local invention, and the practical circulation of flyers and posters.", "argument": "Brown describes participation without central approval. His account prevents the campaign from being represented as one stable ideology or one collective intention.", "context": "An organizer explaining the campaign in an interview. The statement is evidence of his account of internal differences, not a complete record of every participant’s position.", "carrier": "Interview transcription", "locator": "Answer describing establishment of the NYC office", "verification": "Publisher text checked", "relation": "Read against the NYC release and the Boston organizers’ broadcast interview.", "pair": "korda", "sourceTitle": "Interview with the Unabomber for President Political Action Committee NYC"}, {"id": "korda", "title": "Distinct from the Unabomber’s positions", "author": "Chris Korda, interviewed with Lydia Eccles", "date": "9 September 1996", "year": 1996, "kind": "Broadcast", "outlet": "Democracy Now!", "url": "https://www.thetedkarchive.com/library/nomination-for-unabomber-for-president", "quote": "our positions, which of course are distinct from the Unabomber's positions.", "selects": "The public persona and anti-industrial critique as resources for the campaign’s own politics.", "argument": "Korda explicitly distinguishes the organizers’ positions from those of their nominal candidate. The campaign’s use of his notoriety does not establish full ideological agreement.", "context": "This excerpt is from a later transcript mirror of the broadcast. The original programme and audio are linked in the source record; the audio has not been checked against the transcription.", "carrier": "Broadcast transcript mirror", "locator": "Korda’s paragraph introducing the campaign website", "verification": "Transcript checked · audio unchecked", "relation": "Compare with Brown on NYC/Boston differences. Both complicate the idea of one campaign position.", "pair": "brown", "sourceTitle": "Nomination for Unabomber for President"}, {"id": "fulano", "title": "The Unabomber and the Future of Industrial Society", "author": "T. Fulano (David Watson)", "date": "Fall 1996", "year": 1996, "kind": "Magazine", "outlet": "Fifth Estate · no. 348", "url": "https://www.fifthestate.org/archive/348-fall-1996/the-unabomber-and-the-future-of-industrial-society/", "quote": "We need neither condemn nor condone him", "selects": "The manifesto, the media persona, industrial violence, and the limits of individual attacks.", "argument": "Fulano’s critique moves across the text and the social world in which it becomes meaningful. The refusal of a simple condemn/condone choice is part of an argument, not an endorsement stripped of its surrounding criticism.", "context": "The essay became an object of disagreement in the magazine’s letters pages. Read its concluding position beside Eccles’s response.", "carrier": "Publisher transcription", "locator": "Concluding section, paragraph beginning “We need neither…”", "verification": "Publisher text checked", "relation": "Eccles responds to this essay in Fifth Estate #349; Fulano then replies.", "pair": "eccles", "sourceTitle": "The Unabomber and the Future of Industrial Society"}, {"id": "eccles", "title": "Put the system on trial?", "author": "Lydia Eccles", "date": "Summer 1997", "year": 1997, "kind": "Correspondence", "outlet": "Fifth Estate · no. 349", "url": "https://www.fifthestate.org/archive/349-summer-1997/letters-to-the-fifth-estate/", "quote": "Can we put the technological-industrial system on trial?", "selects": "The trial as a public occasion and the possibility of redirecting its political attention.", "argument": "Eccles contests the earlier essay and asks what might be made of the trial. Her intervention shifts the question toward the opportunities created by a mediated event.", "context": "A published letter signed with the Unapack campaign affiliation. This is public correspondence, not the private June 1996 letter referenced in the dissertation’s archival notes.", "carrier": "Published letter · transcription", "locator": "End of Eccles’s letter, before signature and Fulano reply", "verification": "Publisher text checked", "relation": "A documented response to Fulano’s Fall 1996 essay. The same page carries his rebuttal.", "pair": "fulano", "sourceTitle": "Letters to the Fifth Estate [Lydia Eccles letter]"}, {"id": "faun", "title": "Fixed Ideas and Letter Bombs", "author": "Formerly Feral Faun / Wolfi Landstreicher", "date": "Spring 1997", "year": 1997, "kind": "Magazine", "outlet": "Green Anarchist · nos. 45–46", "url": "https://www.thetedkarchive.com/library/wolfi-landstreicher-fixed-ideas-and-letter-bombs", "quote": "FC’s statement has many faults", "selects": "The manifesto’s explanatory concepts, especially psychology and the “power process.”", "argument": "The article takes the manifesto seriously enough to criticize its analytical foundations. Publication in Green Anarchist does not mean that its contributors speak with one voice.", "context": "The archive supplies page images and an unfinished transcription. The scan is the primary visual object; the online OCR contains errors.", "image": "assets/fixed-ideas.jpg", "carrier": "Magazine scan + transcription", "locator": "Opening discussion; displayed page image from the archive", "verification": "Scan available · OCR incomplete", "relation": "Compare with Moore’s focus on ideological motivation rather than treating “anarchist reception” as uniform.", "pair": "moore", "sourceTitle": "Fixed Ideas and Letter Bombs"}, {"id": "moore", "title": "Beyond the Fragments", "author": "John Moore", "date": "Spring 1998", "year": 1998, "kind": "Magazine", "outlet": "Green Anarchist · no. 51", "url": "https://theanarchistlibrary.org/library/john-moore-beyond-the-fragments-a-reaction-to-industrial-society-and-its-future", "quote": "a question of ideological motivation", "selects": "The manifesto’s ideological commitments and competing responses to the bomber.", "argument": "Moore distinguishes his criticism of the text from condemnation of the bombings. His opening challenges the polarity between rejection and romanticization.", "context": "A later transcription identifies the original publication as Green Anarchist #51. The original issue layout is not reproduced here.", "carrier": "Magazine transcription", "locator": "Introduction · paragraph beginning “Rather, however…”", "verification": "Transcription and issue metadata checked", "relation": "An analytical comparison with Feral Faun; this pairing does not assert a direct exchange.", "pair": "faun", "sourceTitle": "Beyond the Fragments: A Reaction to Industrial Society and Its Future"}, {"id": "ace", "title": "Not part of the same movement", "author": "Autonomous Centre of Edinburgh", "date": "31 July 1998", "year": 1998, "kind": "Statement", "outlet": "ACE · supported by Scottish Anarchist Network", "url": "https://libcom.org/article/autonomous-centre-edinburgh-statement-green-anarchist-3171998", "quote": "Our objection is not on the basis of pacifism", "selects": "Green Anarchist’s political positions, revolutionary participation, and the distinction between solidarity and agreement.", "argument": "ACE rejects GA’s politics while opposing state repression of the publication. Supporting freedom to publish and belonging to the same movement are explicitly separated.", "context": "A statement of meeting decisions, later rehosted on libcom in 2016. The statement’s description of GA is an attributed criticism; it must not stand in for all GA contributions.", "carrier": "Statement · later transcription", "locator": "Second substantive paragraph", "verification": "Statement text checked", "relation": "Compare with an individual GA contribution to see why the publication cannot be reduced to either a critic’s description or a single author.", "pair": "moore", "sourceTitle": "Autonomous Centre of Edinburgh statement on Green Anarchist"}, {"id": "tedits", "title": "An inheritance refused", "author": "Ted Kaczynski", "date": "2 September 2012", "year": 2012, "kind": "Correspondence", "outlet": "Letter excerpt to “Anonymous with Caution”", "url": "https://www.thetedkarchive.com/library/ted-kaczynski-on-individualists-tending-toward-savagery-its", "quote": "ITS’ understanding of revolution is at a kindergarten level.", "selects": "ITS’s interpretation of revolution and the relation between technological progress and the whole system.", "argument": "Kaczynski disputes the understanding attributed to ITS. An author’s rejection is part of the textual afterlife, not proof that a reader had no relationship to the work.", "context": "An excerpt of correspondence, reproduced online with a source pointing to Último Reducto’s blog. It is not an image of the original letter.", "carrier": "Letter excerpt · transcription", "locator": "Second paragraph of reproduced excerpt", "verification": "Text and date checked · original letter unavailable", "relation": "Place beside Último Reducto’s critique; both contest attribution and interpretation.", "pair": "ur", "sourceTitle": "Ted Kaczynski on Individualists Tending to the Wild (ITS)"}, {"id": "ur", "title": "Who gets to interpret the text?", "author": "Último Reducto", "date": "Hosted version dated 2015", "year": 2015, "kind": "Critique", "outlet": "Comments on the communiqués from ITS", "url": "https://theanarchistlibrary.org/library/ultimo-reducto-comments-on-the-communiques-from-individualists-tending-toward-the-wild", "quote": "ITS have misinterpreted some aspects of Kaczynski’s ideas", "selects": "Statements ITS attributes to Kaczynski and the textual grounds for disputing them.", "argument": "Último Reducto treats interpretation as something to adjudicate through passages and concepts. The assertion of misreading is the critic’s position, not a neutral fact supplied by the exhibit.", "context": "The hosted item contains material attributed to Último Reducto and Kaczynski. The displayed excerpt belongs to UR’s numbered point 4. The host’s 2015 date does not establish the composition date of every component.", "carrier": "Critique · translated transcription", "locator": "Último Reducto · numbered point 4", "verification": "Relevant section checked", "relation": "Pair with the 2012 letter without treating the host date as proof of the exchange’s sequence.", "pair": "tedits", "sourceTitle": "Comments on the communiques from Individualists Tending toward the Wild"}];
const DOSSIERS = [{"id": "press", "number": "01", "title": "Guilt by association", "period": "APRIL 1996", "subtitle": "The press makes an ideological biography.", "intro": "Once a suspect has a name, the search for explanation reaches into his education, politics, and presumed affinities. These two newspaper objects show that those connections were disputed within coverage itself.", "question": "When does a resemblance become an explanation?", "docs": ["means", "taylor"]}, {"id": "campaign", "number": "02", "title": "Making a candidate", "period": "1996", "subtitle": "Unapack assembles a protest from a persona.", "intro": "An author, a suspect, a candidate who would not serve. Unapack’s participants selected these figures differently. The differences between Boston and New York matter as much as the campaign’s shared name.", "question": "What can be borrowed without being endorsed?", "docs": ["crash", "brown", "korda"]}, {"id": "magazines", "number": "03", "title": "Against a single reading", "period": "1996–1998", "subtitle": "Anarchist magazines become sites of disagreement.", "intro": "Agreement that industrial society demands criticism does not settle what to make of the manifesto, its author, or his violence. Essays and published letters turn those questions into disputes between readers.", "question": "What does a publication’s disagreement make visible?", "docs": ["fulano", "eccles", "faun", "moore"]}, {"id": "boundaries", "number": "04", "title": "The limits of solidarity", "period": "1998", "subtitle": "A movement argues over its own boundaries.", "intro": "Opposing repression need not imply political affiliation. The ACE statement makes that separation explicit. Read its claims alongside the diversity of arguments published within Green Anarchist.", "question": "Who can speak for a movement?", "docs": ["ace", "moore", "faun"]}, {"id": "inheritance", "number": "05", "title": "An inheritance refused", "period": "2012 / 2015", "subtitle": "ITS and the authority to interpret.", "intro": "A text’s circulation does not end in faithful adoption. Kaczynski and Último Reducto contest interpretations associated with ITS. Their objections reveal a struggle over what the texts authorize.", "question": "Does the author control what readers make of a text?", "docs": ["tedits", "ur"]}];
